Decimal dec = Decimal.valueOf('2.25');
Decimal decA = Decimal.valueOf('3');
Decimal decB = Decimal.valueOf('7');
Double dbl = Double.valueOf('2.25');
Double dblA = Double.valueOf('3');
Double dblB = Double.valueOf('7');
Integer intA = -5;
Integer intB = 7;
Long longA = Long.valueOf('-5');
Long longB = Long.valueOf('7');
System.assertEquals(42, Long.valueOf('42').intValue());
System.assertEquals(2.25, Math.abs(dec));
System.assertEquals(2.25, Math.abs(dbl));
System.assertEquals(5, Math.abs(intA));
System.assertEquals(5, Math.abs(longA));
System.assertEquals(1, Math.signum(dec));
System.assertEquals(1, Math.signum(dbl));
System.assertEquals(3.0, Math.ceil(dec));
System.assertEquals(3.0, Math.ceil(dbl));
System.assertEquals(2.0, Math.floor(dec));
System.assertEquals(2.0, Math.floor(dbl));
System.assertEquals(2.0, Math.rint(dec));
System.assertEquals(2.0, Math.rint(dbl));
System.assertEquals(2, Math.round(dec));
System.assertEquals(2, Math.round(dbl));
System.assertEquals(2, Math.roundToLong(dec));
System.assertEquals(2, Math.roundToLong(dbl));
System.assertEquals(7, Math.max(decA, decB));
System.assertEquals(7, Math.max(dblA, dblB));
System.assertEquals(7, Math.max(3, intB));
System.assertEquals(7, Math.max(Long.valueOf('3'), longB));
System.assertEquals(3, Math.min(decA, decB));
System.assertEquals(3, Math.min(dblA, dblB));
System.assertEquals(3, Math.min(3, intB));
System.assertEquals(3, Math.min(Long.valueOf('3'), longB));
System.assertEquals(1, Math.mod(10, 3));
System.assertEquals(1, Math.mod(Long.valueOf('10'), Long.valueOf('3')));
System.assertEquals(3.0, Math.sqrt(decB + Decimal.valueOf('2')));
System.assertEquals(3.0, Math.sqrt(Double.valueOf('9')));
System.assertEquals(2.0, Math.cbrt(Decimal.valueOf('8')));
System.assertEquals(2.0, Math.cbrt(Double.valueOf('8')));
System.assertEquals(8.0, Math.pow(Double.valueOf('2'), Double.valueOf('3')));
System.assert(Math.random() >= 0);
System.assert(Math.random() < 1);
System.assert(Math.abs(Math.acos(Decimal.valueOf('1'))) < 0.000000000001);
System.assert(Math.abs(Math.acos(Double.valueOf('1'))) < 0.000000000001);
System.assert(Math.abs(Math.asin(Decimal.valueOf('1')) - (Math.PI / 2)) < 0.000000000001);
System.assert(Math.abs(Math.asin(Double.valueOf('1')) - (Math.PI / 2)) < 0.000000000001);
System.assert(Math.abs(Math.atan(Decimal.valueOf('1')) - (Math.PI / 4)) < 0.000000000001);
System.assert(Math.abs(Math.atan(Double.valueOf('1')) - (Math.PI / 4)) < 0.000000000001);
System.assert(Math.abs(Math.atan2(Decimal.valueOf('1'), Decimal.valueOf('1')) - (Math.PI / 4)) < 0.000000000001);
System.assert(Math.abs(Math.atan2(Double.valueOf('1'), Double.valueOf('1')) - (Math.PI / 4)) < 0.000000000001);
System.assert(Math.abs(Math.cos(Decimal.valueOf('0')) - 1) < 0.000000000001);
System.assert(Math.abs(Math.cos(Double.valueOf('0')) - 1) < 0.000000000001);
System.assert(Math.abs(Math.cosh(Decimal.valueOf('0')) - 1) < 0.000000000001);
System.assert(Math.abs(Math.cosh(Double.valueOf('0')) - 1) < 0.000000000001);
System.assert(Math.abs(Math.exp(Decimal.valueOf('1')) - Math.E) < 0.000000000001);
System.assert(Math.abs(Math.exp(Double.valueOf('1')) - Math.E) < 0.000000000001);
System.assert(Math.abs(Math.log(Decimal.valueOf('1'))) < 0.000000000001);
System.assert(Math.abs(Math.log(Double.valueOf('1'))) < 0.000000000001);
System.assert(Math.abs(Math.log10(Decimal.valueOf('1000')) - 3) < 0.000000000001);
System.assert(Math.abs(Math.log10(Double.valueOf('1000')) - 3) < 0.000000000001);
System.assert(Math.abs(Math.sin(Decimal.valueOf('0'))) < 0.000000000001);
System.assert(Math.abs(Math.sin(Double.valueOf('0'))) < 0.000000000001);
System.assert(Math.abs(Math.sinh(Decimal.valueOf('0'))) < 0.000000000001);
System.assert(Math.abs(Math.sinh(Double.valueOf('0'))) < 0.000000000001);
System.assert(Math.abs(Math.tan(Decimal.valueOf('0'))) < 0.000000000001);
System.assert(Math.abs(Math.tan(Double.valueOf('0'))) < 0.000000000001);
System.assert(Math.abs(Math.tanh(Decimal.valueOf('0'))) < 0.000000000001);
System.assert(Math.abs(Math.tanh(Double.valueOf('0'))) < 0.000000000001);
Location left = Location.newInstance(37.7749, -122.4194);
Location right = Location.newInstance(34.0522, -118.2437);
System.assertEquals(37.7749, left.getLatitude());
System.assertEquals(-122.4194, left.getLongitude());
System.assert(left.getDistance(right, 'mi') > 300);
System.assert(Location.getDistance(left, right, 'km') > 500);
Exception mathEx = new MathException('math message');
System.assertEquals('math message', mathEx.getMessage());
System.assertEquals('System.MathException', mathEx.getTypeName());
System.assertEquals(0, mathEx.getLineNumber());
System.assertEquals('', mathEx.getStackTraceString());
System.assertEquals(0, mathEx.getInaccessibleFields().size());
mathEx.setMessage('changed math');
System.assertEquals('changed math', mathEx.getMessage());
System.assertEquals(mathEx, mathEx.initCause(new QueryException('math cause')));
System.assertEquals('math cause', mathEx.getCause().getMessage());

